import { SEMANTIC_GOLDEN_PG16 } from './semantic-golden.pg16';
import { SEMANTIC_GOLDEN_PG18 } from './semantic-golden.pg18';

/**
 * The reviewed semantic posture per PostgreSQL major, generated by scripts/check-semantic-posture.ts --write from a
 * migrations-only owner-login database and reviewed like code. A major with no entry is refused at boot in production (D4:
 * an unsupported major fails closed) and only warned about elsewhere. One golden per major, because pg_get_expr deparse
 * may differ between majors. Add `16: SEMANTIC_GOLDEN_PG16` / `18: SEMANTIC_GOLDEN_PG18` when each is generated.
 */
export const SEMANTIC_GOLDEN_BY_MAJOR: Readonly<Record<number, readonly string[]>> = Object.freeze({
  16: SEMANTIC_GOLDEN_PG16,
  18: SEMANTIC_GOLDEN_PG18,
});
